import{_ as a,o as t,c as l,ae as o}from"./chunks/framework.DFTT1zkb.js";const p=JSON.parse('{"title":"主要功能","description":"","frontmatter":{},"headers":[],"relativePath":"features.md","filePath":"features.md"}'),i={name:"features.md"};function n(s,r,e,g,h,u){return t(),l("div",null,[...r[0]||(r[0]=[o('<h1 id="主要功能" tabindex="-1">主要功能 <a class="header-anchor" href="#主要功能" aria-label="Permalink to &quot;主要功能&quot;">​</a></h1><h2 id="远程脚本" tabindex="-1">远程脚本 <a class="header-anchor" href="#远程脚本" aria-label="Permalink to &quot;远程脚本&quot;">​</a></h2><p>远程脚本功能允许您在目标设备上执行各种脚本，实现自动化操作：</p><ul><li><strong>执行预定义脚本</strong>：选择系统内置的脚本执行</li><li><strong>自定义脚本</strong>：编写和执行自定义脚本</li><li><strong>批量执行</strong>：同时向多个目标执行脚本</li><li><strong>定时执行</strong>：设置脚本的执行时间</li></ul><h2 id="窗口检测" tabindex="-1">窗口检测 <a class="header-anchor" href="#窗口检测" aria-label="Permalink to &quot;窗口检测&quot;">​</a></h2><p>窗口检测功能用于监控和管理目标设备的窗口状态：</p><ul><li><strong>窗口列表</strong>：实时查看目标设备打开的窗口</li><li><strong>窗口控制</strong>：显示、隐藏、关闭指定窗口</li><li><strong>进程关联</strong>：查看窗口对应的进程信息</li><li><strong>自动触发</strong>：根据窗口状态自动执行相应操作</li></ul><h2 id="远程桌面" tabindex="-1">远程桌面 <a class="header-anchor" href="#远程桌面" aria-label="Permalink to &quot;远程桌面&quot;">​</a></h2><p>远程桌面功能让您可以远程查看和控制目标设备的桌面：</p><ul><li><strong>实时画面</strong>：查看目标设备的实时屏幕画面</li><li><strong>远程控制</strong>：通过鼠标和键盘远程操作目标设备</li><li><strong>画面质量</strong>：可调节画面质量和传输帧率</li><li><strong>全屏模式</strong>：支持全屏显示，方便远程控制</li></ul><h2 id="文件管理" tabindex="-1">文件管理 <a class="header-anchor" href="#文件管理" aria-label="Permalink to &quot;文件管理&quot;">​</a></h2><p>文件管理功能允许您远程管理目标设备上的文件：</p><ul><li><strong>文件浏览</strong>：浏览目标设备的文件系统</li><li><strong>上传下载</strong>：上传和下载文件</li><li><strong>文件操作</strong>：创建、删除、重命名文件和文件夹</li><li><strong>批量操作</strong>：支持批量上传、下载、删除文件</li></ul><h2 id="内网穿透" tabindex="-1">内网穿透 <a class="header-anchor" href="#内网穿透" aria-label="Permalink to &quot;内网穿透&quot;">​</a></h2><p>windowOP内置了两种Frp方案，支持远程连接：</p><h3 id="sakurafrp" tabindex="-1">SakuraFrp <a class="header-anchor" href="#sakurafrp" aria-label="Permalink to &quot;SakuraFrp&quot;">​</a></h3><ul><li><strong>简单配置</strong>：只需输入Token和隧道ID</li><li><strong>稳定可靠</strong>：使用SakuraFrp的服务</li><li><strong>自动重连</strong>：网络中断后自动重连</li></ul><h3 id="通用frp" tabindex="-1">通用Frp <a class="header-anchor" href="#通用frp" aria-label="Permalink to &quot;通用Frp&quot;">​</a></h3><ul><li><strong>灵活配置</strong>：可自定义服务器地址、端口等</li><li><strong>高度定制</strong>：支持多种协议和配置选项</li><li><strong>跨平台</strong>：可连接到各种Frp服务端</li></ul><h2 id="安全管理" tabindex="-1">安全管理 <a class="header-anchor" href="#安全管理" aria-label="Permalink to &quot;安全管理&quot;">​</a></h2><ul><li><strong>密码保护</strong>：Web界面需要密码验证</li><li><strong>加密通信</strong>：数据传输采用加密协议</li><li><strong>操作日志</strong>：记录所有操作日志</li><li><strong>权限控制</strong>：可设置不同级别的权限</li></ul>',21)])])}const c=a(i,[["render",n]]);export{p as __pageData,c as default};
